 $('tor-disconnect').onclick=()=>{if(dirty&&!confirm('El borrador quedará en este navegador. ¿Cerrar acceso?'))return;localStorage.removeItem('piensa_gh_token');$('tor-token').value='';notify('Acceso cerrado.');};
 (async()=>{try{if(typeof CopaFan==='undefined')await new Promise((ok,no)=>{const style=document.createElement('link');style.rel='stylesheet';style.href=new URL('css/copa-experience.css?v=copa-experience-20261010',CopaConfig.assetBase).href;document.head.append(style);const script=document.createElement('script'),timer=setTimeout(()=>no(Error('No se pudo cargar la vista de tu equipo. Actualiza la página.')),12000);script.onload=()=>{clearTimeout(timer);ok();};script.onerror=()=>{clearTimeout(timer);no(Error('No se pudo cargar la vista de tu equipo. Actualiza la página.'));};script.src=new URL('js/copa-fan.js?v=copa-experience-20261010',CopaConfig.assetBase).href;document.head.append(script);});updateFanNavigation();if(params.get('id'))await open(params.get('id'));else if(organizer||!(await restoreFavorite()))await refresh();}catch(e){app.innerHTML='<p>No se pudo abrir esta vista. <a href="./">Volver a la copa</a></p>';notify(e.message,true);}})();
